window.RYVO_VORLAGEN = function vorlagenBauen(WB, tr, karte, stuecke) {
const vorl = [];
for (const [d, e] of Object.entries(WB)) {
if (!/\{\d\}/.test(d)) continue;
const teile = d.trim().split(/\{(\d)\}/), idx = [], fest = [];
let re = '^';
teile.forEach((x, i) => { if (i % 2) { idx.push(+x); re += '((?:(?! · )[\\s\\S])+?)'; } else { re += x.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); fest.push(x); } });
const anker = fest.reduce((a, b) => (b.trim().length > a.length ? b.trim() : a), '');
if (anker.length >= 3) vorl.push({ re: new RegExp(re + '$'), idx, ziel: String(e), anker, n: fest.join('').length });
}
vorl.sort((a, b) => b.n - a.n);
const finde = (k) => {
for (const v of vorl) {
if (!k.includes(v.anker)) continue;
const m = v.re.exec(k); if (!m) continue;
return v.ziel.replace(/\{(\d)\}/g, (x, i) => { const j = v.idx.indexOf(+i); if (j < 0) return x; const w = m[j + 1]; return /[A-Za-zÄÖÜäöüß]{2}/.test(w) ? tr(w) : w; });
}
return undefined;
};
const teil = (t) => { const kern = t.trim(); if (!kern) return t; const d = karte(kern) ?? finde(kern); return d !== undefined ? t.replace(kern, () => d) : null; };
return (norm) => {
const ganz = teil(norm); if (ganz !== null || !norm.includes(' · ')) return ganz;
const teile = norm.split(' · '), neu = teile.map(teil);
return neu.some((x) => x !== null) ? neu.map((x, i) => (x !== null ? x : stuecke(teile[i]))).join(' · ') : null;
};
};
